package com.andye.warmod.radar.client.gui;
import net.minecraft.util.Mth;
public final class RadarMapTransform{private double centerWorldX,centerWorldZ,blocksPerPixel=8;public double screenX(double worldX,int left,int width){return left+width*.5+(worldX-centerWorldX)/blocksPerPixel;}public double screenY(double worldZ,int top,int height){return top+height*.5+(worldZ-centerWorldZ)/blocksPerPixel;}public double worldX(double screenX,int left,int width){return centerWorldX+(screenX-left-width*.5)*blocksPerPixel;}public double worldZ(double screenY,int top,int height){return centerWorldZ+(screenY-top-height*.5)*blocksPerPixel;}public void panPixels(double dx,double dy){centerWorldX-=dx*blocksPerPixel;centerWorldZ-=dy*blocksPerPixel;}public void zoomAt(double scroll,double mouseX,double mouseY,int left,int top,int width,int height){double wx=worldX(mouseX,left,width),wz=worldZ(mouseY,top,height);blocksPerPixel=Mth.clamp(blocksPerPixel*Math.pow(1.18,-scroll),.20,131072);centerWorldX=wx-(mouseX-left-width*.5)*blocksPerPixel;centerWorldZ=wz-(mouseY-top-height*.5)*blocksPerPixel;}public void center(double x,double z){centerWorldX=x;centerWorldZ=z;}public void fit(double minX,double minZ,double maxX,double maxZ,int width,int height){double spanX=Math.max(16,maxX-minX),spanZ=Math.max(16,maxZ-minZ);center((minX+maxX)*.5,(minZ+maxZ)*.5);blocksPerPixel=Mth.clamp(Math.max(spanX/(width*.78),spanZ/(height*.78)),.20,131072);}public double centerWorldX(){return centerWorldX;}public double centerWorldZ(){return centerWorldZ;}public double blocksPerPixel(){return blocksPerPixel;}}
